using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Swashbuckle.AspNetCore.Annotations;using GraphApi.Models.TKT.PrioridadEstickets;using GraphApi.Services.TKT.PrioridadEstickets;namespace GraphApi.Controllers.TKT.PrioridadEstickets{    /// <summary>    /// Gestión de PrioridadEstickets: consulta, creación, actualización y borrado.    /// </summary>    [ApiController]    [Authorize]    [Route("TKT/[controller]")]    [Produces("application/json")]    [SwaggerTag("Operaciones sobre PrioridadEstickets")]    public class PrioridadEsticketsController : Controller    {        private readonly IPrioridadEsticketsService _objService;        public PrioridadEsticketsController(IPrioridadEsticketsService objService)        {            _objService = objService;        }        /// <summary>        /// Obtiene todos los PrioridadEstickets, con filtros opcionales.        /// </summary>        /// <param name="userId">Id de usuario (header "UserID").</param>        /// <param name="windowName">Nombre de la aplicación (header "WindowName").</param>        /// <param name="prioridadTicketID">PrioridadTicketID</param>        /// <param name="prioridadTicket">PrioridadTicket</param>        /// <param name="bEliminado">bEliminado</param>        /// <returns>Listado de PrioridadEstickets</returns>        [HttpGet]        [SwaggerOperation(            Summary = "Listar PrioridadEstickets",            Description = "Devuelve PrioridadEstickets aplicando filtros opcionales."        )]        [ProducesResponseType(typeof(IEnumerable<clReadPrioridadEstickets>), StatusCodes.Status200OK)]        public async Task<ActionResult<IEnumerable<clReadPrioridadEstickets>>> GetAll(            [FromHeader(Name = "UserID")] int nUserId,            [FromHeader(Name = "WindowName")] string sWindowName,            [FromQuery] int? prioridadTicketID,            [FromQuery] string? prioridadTicket,            [FromQuery] bool? bEliminado,            [FromQuery] string? columnNames)        {            var vList = await _objService.GetPrioridadEsticketsDynamic(                prioridadTicketID,                 prioridadTicket,                 bEliminado,                 columnNames, nUserId, sWindowName);              return vList.Count()==0  ? NotFound() :  Ok(vList);        }        /// <summary>        /// Crea un nuevo PrioridadEsticket.        /// </summary>        /// <param name="userId">Id de usuario (header "UserID").</param>        /// <param name="windowName">Nombre de la aplicación (header "WindowName").</param>        /// <param name="input">Datos del PrioridadEsticket a crear.</param>        /// <returns>El PrioridadEsticket recién creado.</returns>        [HttpPost]        [SwaggerOperation(            Summary = "Crear PrioridadEstickets",            Description = "Inserta un nuevo PrioridadEsticket en la base de datos."        )]        [ProducesResponseType(typeof(clReadPrioridadEstickets), StatusCodes.Status201Created)]        public async Task<ActionResult<clReadPrioridadEstickets>> Create(            [FromHeader(Name = "UserID")] int nUserId,            [FromHeader(Name = "WindowName")] string sWindowName,            [FromBody] clCreatePrioridadEstickets objInput)        {            var vCreated = await _objService.CreatePrioridadEstickets(objInput, nUserId, sWindowName);            return vCreated is null ? NoContent() : vCreated;        }        /// <summary>        /// Actualización parcial de PrioridadEsticket.        /// </summary>        /// <param name="userId">Id de usuario (header "UserID").</param>        /// <param name="windowName">Nombre de la aplicación (header "WindowName").</param>        /// <param name="input">Campos a actualizar y el ID del PrioridadEsticket.</param>        /// <returns>El PrioridadEsticket actualizado.</returns>        [HttpPatch]        [SwaggerOperation(            Summary = "Actualizar PrioridadEstickets",            Description = "Actualiza uno o varios campos de PrioridadEsticket existente."        )]        [ProducesResponseType(typeof(clReadPrioridadEstickets), StatusCodes.Status200OK)]        public async Task<ActionResult<clReadPrioridadEstickets>> Patch(            [FromHeader(Name = "UserID")] int nUserId,            [FromHeader(Name = "WindowName")] string sWindowName,            [FromBody] clUpdatePrioridadEstickets objInput)        {            var vUpdated = await _objService.UpdatePrioridadEstickets(objInput, nUserId, sWindowName);            return vUpdated is null ? NotFound() : Ok(vUpdated);        }        /// <summary>        /// Elimina un PrioridadEsticket por su ID.        /// </summary>        [HttpDelete("{nPrioridadEsticketsID:int}")]        [SwaggerOperation(            Summary = "Eliminar PrioridadEsticket",            Description = "Borra un PrioridadEsticket si existe."        )]        [ProducesResponseType(StatusCodes.Status204NoContent)]        public async Task<IActionResult> Delete(int nPrioridadEsticketsID)        {            var success = await _objService.DeletePrioridadEstickets(nPrioridadEsticketsID);            return success ? NoContent() : NotFound();        }    }}